#!/usr/bin/env python3
"""Snapshot generated bytes, run a generator, fail on changes (including new files).

Use: python3 tools/check_generated.py web/src/lib/wire -- GENERATOR ARGS...
Leaves changed output for inspection. Does not reset or depend on git status.
"""
import hashlib
from pathlib import Path
import subprocess
import sys


def snapshot(root):
    return {str(p.relative_to(root)): hashlib.sha256(p.read_bytes()).hexdigest()
            for p in root.rglob('*') if p.is_file()}


def main(argv):
    if len(argv) < 4 or argv[2] != '--':
        raise SystemExit(__doc__)
    root = Path(argv[1])
    before = snapshot(root)
    result = subprocess.run(argv[3:])
    if result.returncode:
        return result.returncode
    after = snapshot(root)
    changed = sorted(key for key in before.keys() | after.keys() if before.get(key) != after.get(key))
    if changed:
        print('generated output changed:\n' + '\n'.join(changed), file=sys.stderr)
        return 1
    return 0


if __name__ == '__main__':
    raise SystemExit(main(sys.argv))
